class Solution {
public:
    long long f(int l, int r, vector<int>& a, vector<vector<long long>>& dp) {
        if (r - l + 1 <= 2) return 0;
        long long &res = dp[l][r];
        if (res != LLONG_MIN) return res;
        res = max({(long long)a[l] + a[l+1] + f(l+2, r, a, dp),
                   (long long)a[r-1] + a[r] + f(l, r-2, a, dp),
                   (long long)a[l] + a[r] + f(l+1, r-1, a, dp)});
        return res;
    }
    long long maximumScore(vector<int>& nums) {
        int n = nums.size();
        vector<vector<long long>> dp(n, vector<long long>(n, LLONG_MIN));
        return f(0, n - 1, nums, dp);
    }
};

