class Solution {
    private int[] a;
    private Long[][] dp;
    public long maximumScore(int[] nums) {
        a = nums;
        int n = nums.length;
        dp = new Long[n][n];
        return f(0, n - 1);
    }
    private long f(int l, int r) {
        if (r - l + 1 <= 2) return 0;
        if (dp[l][r] != null) return dp[l][r];
        long res = Math.max(
            a[l] + a[l + 1] + f(l + 2, r),
            Math.max(a[r - 1] + a[r] + f(l, r - 2),
                     a[l] + a[r] + f(l + 1, r - 1)));
        return dp[l][r] = res;
    }
}

