var maximumScore = function(nums) {
    const memo = new Map();
    const key = (l, r) => l * 100001 + r;
    function f(l, r) {
        if (r - l + 1 <= 2) return 0;
        const k = key(l, r);
        if (memo.has(k)) return memo.get(k);
        const res = Math.max(
            nums[l] + nums[l + 1] + f(l + 2, r),
            nums[r - 1] + nums[r] + f(l, r - 2),
            nums[l] + nums[r] + f(l + 1, r - 1)
        );
        memo.set(k, res);
        return res;
    }
    return f(0, nums.length - 1);
};

