class Solution:
    def maximumScore(self, nums: List[int]) -> int:
        total = sum(nums)
        n = len(nums)
        best_keep = 0
        if n % 2 == 1:
            best_keep = min(nums)
        if n >= 2:
            pair = min(nums[i] + nums[i + 1] for i in range(n - 1))
            if n % 2 == 0 or True:
                best_keep = min(best_keep, pair) if n % 2 == 0 else min(best_keep, pair)
        return total - best_keep

