class Solution {
public:
    long long maximumScore(vector<int>& nums) {
        int n = nums.size();
        long long total = accumulate(nums.begin(), nums.end(), 0LL);
        long long bestKeep = 0;
        if (n % 2 == 1) bestKeep = *min_element(nums.begin(), nums.end());
        if (n >= 2) {
            long long pair = LLONG_MAX;
            for (int i = 0; i + 1 < n; ++i)
                pair = min(pair, (long long)nums[i] + nums[i + 1]);
            bestKeep = min(bestKeep, pair);
        }
        return total - bestKeep;
    }
};

