class Solution {
    public long maximumScore(int[] nums) {
        int n = nums.length;
        long total = 0;
        for (int x : nums) total += x;
        long bestKeep = 0;
        if (n % 2 == 1) {
            bestKeep = Long.MAX_VALUE;
            for (int x : nums) bestKeep = Math.min(bestKeep, x);
        }
        if (n >= 2) {
            long pair = Long.MAX_VALUE;
            for (int i = 0; i + 1 < n; i++)
                pair = Math.min(pair, (long) nums[i] + nums[i + 1]);
            bestKeep = Math.min(bestKeep, pair);
        }
        return total - bestKeep;
    }
}

